      def generated_rule_sections
        [
          rule_section(:goal, GameRoomRules.translate("Goal"),
            GameRoomRules.translate("Two to eight players take turns rolling five dice and filling their own score sheets. Each row has three spaces. On each turn you fill the first empty space in one row. Once every sheet is full, the player with the highest total, including bonuses, wins. Players tied for the highest score share the win.")),
          rule_section(:turn, GameRoomRules.translate("Your turn"),
