          rule_section(:scores, GameRoomRules.translate("Combinations"),
            GameRoomRules.translate("- One pair, two pairs of different values, three of a kind and four of a kind score the sum of the dice forming that combination."),
            GameRoomRules.translate("- A small straight consists of four consecutive values; a large straight uses five. Add the values in the straight. If there are two possible small straights, the higher one counts."),
            GameRoomRules.translate("- A full house is three dice of one value and two of another. A full house and five of a kind score the sum of all five dice."),
            GameRoomRules.translate("- Chance also scores the sum of all five dice and accepts any roll.")),
          rule_section(:school, GameRoomRules.translate("School and reserve"),
            GameRoomRules.translate("The School section has a row for each value from one to six. To record a result, you need three dice of that value, counting any reserve you have built up. You must have at least one in the current roll. Score only the dice actually rolled. For example, four sixes score 24 and add one six to your reserve. Later, two sixes can use that reserve six to qualify, but still score only 12.")),
          rule_section(:bonuses, GameRoomRules.translate("Bonuses"),
