            rule_section(:school, "Szko\u0142a i rezerwa",
              "W szkole jest po jednym wierszu na ka\u017Cd\u0105 liczb\u0119 oczek. Do wpisu potrzeba trzech ko\u015Bci tej warto\u015Bci, ale brakuj\u0105ce mo\u017Cesz uzupe\u0142ni\u0107 z rezerwy. Przynajmniej jedna musi pochodzi\u0107 z bie\u017C\u0105cego rzutu. Punkty dostajesz tylko za wyrzucone ko\u015Bci. Przy czterech sz\u00F3stkach wpisujesz 24 punkty, a jedna sz\u00F3stka trafia do rezerwy. Gdy p\u00F3\u017Aniej wyrzucisz dwie sz\u00F3stki, mo\u017Cesz zu\u017Cy\u0107 t\u0119 z rezerwy i wpisa\u0107 12 punkt\u00F3w."),
            rule_section(:bonuses, "Premie",
              "Pierwszy gracz, kt\u00F3ry wype\u0142ni dany wiersz bez skre\u015Ble\u0144, dostaje premi\u0119 r\u00F3wn\u0105 wynikowi z ostatniego pola. Pierwszy, kto wype\u0142ni dan\u0105 kolumn\u0119 bez skre\u015Ble\u0144, dostaje 60 punkt\u00F3w. Skre\u015Blenie w szkole odbiera zdobyte premie. Do premii za kolumn\u0119 potrzebujesz wpisu w ka\u017Cdej kategorii, r\u00F3wnie\u017C poza szko\u0142\u0105."),
            rule_section(:options, "Ustawienia sto\u0142u",
              "Przy jednej lub dw\u00F3ch kolumnach nie ma premii. Opcjonalne kategorie parzyste i nieparzyste licz\u0105 sum\u0119 oczek, je\u015Bli wszystkie ko\u015Bci s\u0105 odpowiednio parzyste albo nieparzyste. Sta\u0142a punktacja daje 20 za tr\u00F3jk\u0119, 25 za ma\u0142ego strita, 30 za du\u017Cego, 35 za fulla, 40 za karet\u0119 i 50 za genera\u0142a. Opcja podwajania wyniku z pierwszego rzutu nie obejmuje szko\u0142y. W surowym wariancie skre\u015Blenie w szkole blokuje tak\u017Ce przysz\u0142e premie."),
            rule_section(:controls, "Klawiatura",
              "Enter: rozpocznij tur\u0119 rzutem pi\u0119cioma ko\u015B\u0107mi. P\u00F3\u017Aniej przerzu\u0107 zaznaczone ko\u015Bci albo otw\u00F3rz tabel\u0119 zapisu, je\u015Bli \u017Cadna nie jest zaznaczona. W tabeli zapisz wynik w wybranym wierszu. Po trzecim rzucie tabela pojawia si\u0119 automatycznie.",
              "1\u20136: zaznacz do przerzutu jedn\u0105 ko\u015B\u0107 o tej warto\u015Bci.",
              "Shift+1\u20136: odznacz jedn\u0105 wybran\u0105 ko\u015B\u0107 o tej warto\u015Bci.",
              "Strza\u0142ki: g\u00F3ra i d\u00F3\u0142 wybieraj\u0105 wiersz, a lewo i prawo pozwalaj\u0105 sprawdzi\u0107 jego wpisy oraz podsumowania. Pe\u0142ne wiersze s\u0105 pomijane w tabeli zapisu.",
              "B: otw\u00F3rz tabel\u0119 punktacji w osobnym oknie.",
              "Escape: zamknij osobne okno tabeli bez zapisania wyniku.",
              "Spacja: odczytaj ko\u015Bci, a w polu rzutu tak\u017Ce ich zaznaczenie.",
              "D: odczytaj ostatni rzut.",
              "V: przejrzyj swoj\u0105 tabel\u0119.",
              "Shift+V: przejrzyj tabel\u0119 innego gracza.",
              "F: przejrzyj w\u0142asne niewype\u0142nione wiersze.",
              "S: odczytaj wyniki z premiami.",
              "Shift+S: odczytaj sum\u0119 zapisanych punkt\u00F3w.")
          ]
        when "ru"
          [
            rule_section(:goal, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0438\u0433\u0440\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044E\u0442 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u0412\u044B \u0431\u0440\u043E\u0441\u0430\u0435\u0442\u0435 \u043F\u044F\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0435 \u0441\u0432\u043E\u044E \u0442\u0430\u0431\u043B\u0438\u0446\u0443. \u0412 \u043A\u0430\u0436\u0434\u043E\u0439 \u0441\u0442\u0440\u043E\u043A\u0435 \u0442\u0440\u0438 \u043A\u043B\u0435\u0442\u043A\u0438; \u0437\u0430 \u0445\u043E\u0434 \u0432\u044B \u0437\u0430\u043D\u0438\u043C\u0430\u0435\u0442\u0435 \u043F\u0435\u0440\u0432\u0443\u044E \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u0441\u0442\u0440\u043E\u043A\u0438. \u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u0442\u0430\u0431\u043B\u0438\u0446\u044B \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u044B, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0438\u0433\u0440\u043E\u043A \u0441 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043F\u0440\u0435\u043C\u0438\u0439. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043B\u0443\u0447\u0448\u0438\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u043F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F."),
            rule_section(:turn, "\u0425\u043E\u0434",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u0447\u0442\u043E\u0431\u044B \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u0435 \u043F\u044F\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u0440\u0430\u0437\u0443 \u0438\u043B\u0438 \u0435\u0449\u0451 \u0434\u0432\u0430 \u0440\u0430\u0437\u0430 \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0447\u0430\u0441\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u0426\u0438\u0444\u0440\u0430 \u043E\u0442 1 \u0434\u043E 6 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0434\u0438\u043D \u043A\u0443\u0431\u0438\u043A \u0441 \u0442\u0430\u043A\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0430. Shift \u0441 \u0442\u043E\u0439 \u0436\u0435 \u0446\u0438\u0444\u0440\u043E\u0439 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0432\u044B\u0431\u043E\u0440 \u043E\u0434\u043D\u043E\u0433\u043E \u043A\u0443\u0431\u0438\u043A\u0430. Enter \u043F\u0435\u0440\u0435\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438, \u0430 \u0435\u0441\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043E \u2014 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0442\u0430\u0431\u043B\u0438\u0446\u0443 \u0437\u0430\u043F\u0438\u0441\u0438.",
              "\u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u0442\u0430\u0431\u043B\u0438\u0446\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0432 \u0438\u0433\u0440\u043E\u0432\u043E\u043C \u043F\u043E\u043B\u0435. \u0421\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u043E\u043A\u0443; \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0435\u0451 \u0437\u0430\u043F\u0438\u0441\u0438, \u0441\u0443\u043C\u043C\u0443 \u0438 \u0440\u0435\u0437\u0435\u0440\u0432. Enter \u0432 \u043B\u044E\u0431\u043E\u043C \u0441\u0442\u043E\u043B\u0431\u0446\u0435 \u0437\u0430\u043F\u0438\u0448\u0435\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0432 \u043F\u0435\u0440\u0432\u0443\u044E \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0441\u0442\u0440\u043E\u043A\u0438. \u0411\u0440\u043E\u0441\u043E\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442\u044C \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u043C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0435: \u043A\u043B\u0435\u0442\u043A\u0430 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043D\u044F\u0442\u0430 \u0431\u0435\u0437 \u043D\u0430\u0447\u0438\u0441\u043B\u0435\u043D\u0438\u044F \u043E\u0447\u043A\u043E\u0432."),
            rule_section(:scores, "\u041A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438",
              "- \u041F\u0430\u0440\u0430, \u0434\u0432\u0435 \u0440\u0430\u0437\u043D\u044B\u0435 \u043F\u0430\u0440\u044B, \u0442\u0440\u043E\u0439\u043A\u0430 \u0438 \u043A\u0430\u0440\u0435 \u0434\u0430\u044E\u0442 \u0441\u0443\u043C\u043C\u0443 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u043A\u0443\u0431\u0438\u043A\u043E\u0432, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0438\u0445 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u044E.",
              "- \u041C\u0430\u043B\u044B\u0439 \u0441\u0442\u0440\u0438\u0442 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u0435\u043B, \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u2014 \u0438\u0437 \u043F\u044F\u0442\u0438. \u0421\u043B\u043E\u0436\u0438\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432 \u0441\u0442\u0440\u0438\u0442\u0435. \u0415\u0441\u043B\u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u044B \u0434\u0432\u0430 \u043C\u0430\u043B\u044B\u0445 \u0441\u0442\u0440\u0438\u0442\u0430, \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u043E\u043B\u044C\u0448\u0438\u0439.",
              "- \u0424\u0443\u043B\u043B-\u0445\u0430\u0443\u0441 \u2014 \u044D\u0442\u043E \u0442\u0440\u043E\u0439\u043A\u0430 \u0438 \u043F\u0430\u0440\u0430. \u0414\u043B\u044F \u0444\u0443\u043B\u043B-\u0445\u0430\u0443\u0441\u0430 \u0438 \u043F\u044F\u0442\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0441\u043B\u043E\u0436\u0438\u0442\u0435 \u0432\u0441\u0435 \u043F\u044F\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439.",
              "- \u0412 \u0441\u0442\u0440\u043E\u043A\u0443 \u00AB\u0428\u0430\u043D\u0441\u00BB \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u043B\u044E\u0431\u043E\u0439 \u0431\u0440\u043E\u0441\u043E\u043A; \u043E\u043D \u0434\u0430\u0451\u0442 \u0441\u0443\u043C\u043C\u0443 \u0432\u0441\u0435\u0445 \u043F\u044F\u0442\u0438 \u043A\u0443\u0431\u0438\u043A\u043E\u0432."),
            rule_section(:school, "\u0428\u043A\u043E\u043B\u0430 \u0438 \u0440\u0435\u0437\u0435\u0440\u0432",
              "\u0412 \u0448\u043A\u043E\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0441\u0432\u043E\u044F \u0441\u0442\u0440\u043E\u043A\u0430. \u0414\u043B\u044F \u0437\u0430\u043F\u0438\u0441\u0438 \u043D\u0443\u0436\u043D\u044B \u0442\u0440\u0438 \u043A\u0443\u0431\u0438\u043A\u0430 \u0441 \u044D\u0442\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C; \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0438\u0435 \u043C\u043E\u0436\u043D\u043E \u0432\u0437\u044F\u0442\u044C \u0438\u0437 \u0440\u0435\u0437\u0435\u0440\u0432\u0430. \u0425\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u0438\u043D \u043A\u0443\u0431\u0438\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u0432\u044B\u043F\u0430\u0441\u0442\u044C \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u0431\u0440\u043E\u0441\u043A\u0435. \u041E\u0447\u043A\u0438 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0437\u0430 \u0432\u044B\u043F\u0430\u0432\u0448\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0438. \u0427\u0435\u0442\u044B\u0440\u0435 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0438 \u0434\u0430\u044E\u0442 24 \u043E\u0447\u043A\u0430 \u0438 \u043E\u0434\u043D\u0443 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0443 \u0432 \u0440\u0435\u0437\u0435\u0440\u0432. \u0415\u0441\u043B\u0438 \u043F\u043E\u0437\u0436\u0435 \u0432\u044B\u043F\u0430\u0434\u0443\u0442 \u0434\u0432\u0435 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0438, \u0432\u043E\u0437\u044C\u043C\u0438\u0442\u0435 \u0442\u0440\u0435\u0442\u044C\u044E \u0438\u0437 \u0440\u0435\u0437\u0435\u0440\u0432\u0430 \u0438 \u0437\u0430\u043F\u0438\u0448\u0438\u0442\u0435 12 \u043E\u0447\u043A\u043E\u0432."),
            rule_section(:bonuses, "\u041F\u0440\u0435\u043C\u0438\u0438",
              "\u041A\u0442\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u0442 \u0434\u0430\u043D\u043D\u0443\u044E \u0441\u0442\u0440\u043E\u043A\u0443 \u0431\u0435\u0437 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0439, \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u0440\u0435\u043C\u0438\u044E \u0432 \u0440\u0430\u0437\u043C\u0435\u0440\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0437\u0430\u043F\u0438\u0441\u0438. \u041F\u0435\u0440\u0432\u044B\u0439 \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u0432\u0448\u0438\u0439 \u0434\u0430\u043D\u043D\u044B\u0439 \u0441\u0442\u043E\u043B\u0431\u0435\u0446 \u0431\u0435\u0437 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 60 \u043E\u0447\u043A\u043E\u0432. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u043D\u0443\u0436\u043D\u044B \u0437\u0430\u043F\u0438\u0441\u0438 \u0432\u043E \u0432\u0441\u0435\u0445 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044F\u0445, \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0448\u043A\u043E\u043B\u0435. \u0417\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0432 \u0448\u043A\u043E\u043B\u0435 \u043B\u0438\u0448\u0430\u0435\u0442 \u0443\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u0435\u043C\u0438\u0439."),
            rule_section(:options, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
              "\u041F\u0440\u0438 \u043E\u0434\u043D\u043E\u043C \u0438\u043B\u0438 \u0434\u0432\u0443\u0445 \u0441\u0442\u043E\u043B\u0431\u0446\u0430\u0445 \u043F\u0440\u0435\u043C\u0438\u0439 \u043D\u0435\u0442. \u0412 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u0447\u0451\u0442\u043D\u044B\u0445 \u0438 \u043D\u0435\u0447\u0451\u0442\u043D\u044B\u0445 \u0447\u0438\u0441\u0435\u043B \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u0443\u043C\u043C\u0443 \u0431\u0440\u043E\u0441\u043A\u0430, \u0435\u0441\u043B\u0438 \u0432\u0441\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u0438\u043C\u0435\u044E\u0442 \u043D\u0443\u0436\u043D\u0443\u044E \u0447\u0451\u0442\u043D\u043E\u0441\u0442\u044C. \u041F\u0440\u0438 \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0439 \u043E\u0446\u0435\u043D\u043A\u0435 \u0442\u0440\u043E\u0439\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 20, \u043C\u0430\u043B\u044B\u0439 \u0441\u0442\u0440\u0438\u0442 \u2014 25, \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u2014 30, \u0444\u0443\u043B\u043B-\u0445\u0430\u0443\u0441 \u2014 35, \u043A\u0430\u0440\u0435 \u2014 40, \u043F\u044F\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u2014 50. \u0423\u0434\u0432\u043E\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u043D\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0432 \u0448\u043A\u043E\u043B\u0435. \u0412 \u0441\u0442\u0440\u043E\u0433\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0437\u0430\u0447\u0451\u0440\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0432 \u0448\u043A\u043E\u043B\u0435 \u043B\u0438\u0448\u0430\u0435\u0442 \u0438 \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u043F\u0440\u0435\u043C\u0438\u0439."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0430",
              "Enter: \u043D\u0430\u0447\u0430\u0442\u044C \u0445\u043E\u0434 \u0431\u0440\u043E\u0441\u043A\u043E\u043C \u043F\u044F\u0442\u0438 \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u0417\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0442\u0430\u0431\u043B\u0438\u0446\u0443, \u0435\u0441\u043B\u0438 \u043D\u0438 \u043E\u0434\u0438\u043D \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043D. \u0412 \u0442\u0430\u0431\u043B\u0438\u0446\u0435 \u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0432 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u0441\u0442\u0440\u043E\u043A\u0443. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u0442\u0430\u0431\u043B\u0438\u0446\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
              "1\u20136: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0430 \u043E\u0434\u0438\u043D \u043A\u0443\u0431\u0438\u043A \u0441 \u0442\u0430\u043A\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C.",
              "Shift+1\u20136: \u0441\u043D\u044F\u0442\u044C \u0432\u044B\u0431\u043E\u0440 \u043E\u0434\u043D\u043E\u0433\u043E \u043A\u0443\u0431\u0438\u043A\u0430 \u0441 \u0442\u0430\u043A\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C.",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0441\u0442\u0440\u043E\u043A\u0443, \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0435\u0451 \u0437\u0430\u043F\u0438\u0441\u0438 \u0438 \u0438\u0442\u043E\u0433\u0438. \u0417\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u044E\u0442\u0441\u044F \u0434\u043B\u044F \u0437\u0430\u043F\u0438\u0441\u0438.",
              "B: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0442\u0430\u0431\u043B\u0438\u0446\u0443 \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u043C \u043E\u043A\u043D\u0435.",
              "Escape: \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435 \u043E\u043A\u043D\u043E \u0442\u0430\u0431\u043B\u0438\u0446\u044B \u0431\u0435\u0437 \u0437\u0430\u043F\u0438\u0441\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u0438, \u0430 \u0432 \u043F\u043E\u043B\u0435 \u0431\u0440\u043E\u0441\u043A\u0430 \u0442\u0430\u043A\u0436\u0435 \u0438\u0445 \u0432\u044B\u0431\u043E\u0440.",
              "D: \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0431\u0440\u043E\u0441\u043E\u043A.",
              "V: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u0432\u043E\u044E \u0442\u0430\u0431\u043B\u0438\u0446\u0443.",
              "Shift+V: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0442\u0430\u0431\u043B\u0438\u0446\u0443 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "F: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u0432\u043E\u0438 \u043D\u0435\u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0435 \u0441\u0442\u0440\u043E\u043A\u0438.",
              "S: \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0441\u0447\u0451\u0442 \u0441 \u043F\u0440\u0435\u043C\u0438\u044F\u043C\u0438.",
              "Shift+S: \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0441\u0443\u043C\u043C\u0443 \u0437\u0430\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432.")
          ]
